:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-mist-panel: #f8f8fd;
  --color-fog-card: #f1f1f9;
  --color-frosted-tile: #f0f0ff;
  --color-frosted-chip: #e1e2fe;
  --color-aubergine-ink: #15002c;
  --color-slate-text: #70708f;
  --color-pewter-caption: #8d8da5;
  --color-iron-rule: #5a5a72;
  --color-steel-border: #a9a9bc;
  --color-signal-violet: #6307f8;
  --color-orchid-glow: #c185e5;
  --color-amethyst-tile: #743899;

  /* Typography — Font Families */
  --font-sanomat: "Sanomat", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.58;
  --tracking-small: -0.24px;
  --text-caption: 13px;
  --leading-caption: 1.46;
  --tracking-caption: -0.26px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: -0.28px;
  --text-body: 15px;
  --leading-body: 1.4;
  --tracking-body: -0.3px;
  --text-body-lg: 17px;
  --leading-body-lg: 1.88;
  --tracking-body-lg: -0.34px;
  --text-subheading: 19px;
  --leading-subheading: 1.32;
  --tracking-subheading: -0.38px;
  --text-heading-sm: 30px;
  --leading-heading-sm: 1.27;
  --tracking-heading-sm: 0px;
  --text-heading: 40px;
  --leading-heading: 1.35;
  --tracking-heading: 0px;
  --text-heading-lg: 45px;
  --leading-heading-lg: 1.2;
  --tracking-heading-lg: 0px;
  --text-display: 130px;
  --leading-display: 0.92;
  --tracking-display: -2.6px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-60: 60px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-140: 140px;

  /* Layout */
  --layout-max-width: 1440px;
  --layout-section-gap: 80px;
  --layout-card-padding: 28px;
  --layout-element-gap: 16px;
  --layout-nav-height: 77px;
  --layout-cta-max-width: 410px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 14px;
  --radius-2xl: 16px;
  --radius-3xl: 40px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-cards: 14px;
  --radius-sections: 16px;
  --radius-small-cards: 16px;
  --radius-images: 12px;
  --radius-inner-tiles: 12px;
  --radius-inputs: 8px;
  --radius-small-elements: 4px;
  --radius-avatars: 50%;
  --radius-nav: 0px 0px 40px 40px;

  /* Shadows */
  --shadow-subtle: 0px 2px 2px 0px rgba(0, 0, 0, 0.02), 0px 4px 5px 0px rgba(0, 0, 0, 0.05);
  --shadow-sm: 3px 3px 6px 0px rgba(0, 0, 0, 0.18);
  --shadow-lg: 0px 25px 50px -12px rgba(0, 0, 0, 0.25);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-mist-panel: #f8f8fd;
  --surface-fog-card: #f1f1f9;
  --surface-frosted-chip: #e1e2fe;
  --surface-aubergine-ink: #15002c;
}

